function reverseString(str) {
   // Step 1: Convert the string to an array using split()
   let strArray = str.split(""); // "hello" becomes ["h", "e", "l", "l", "o"]   ---> You can also use spread operator in place of .split

   // Step 2: Reverse the array using reverse()
   let reversedArray = strArray.reverse(); // ["h", "e", "l", "l", "o"] becomes ["o", "l", "l", "e", "h"]

   // Step 3: Join the reversed array back into a string using join()
   let reversedStr = reversedArray.join(""); // ["o", "l", "l", "e", "h"] becomes "olleh"

   // Step 4: Return the reversed string
   return reversedStr;
}

