       return "Please enter a valid numeric temperature.";
   }

   if (unit === "C") {
       // Celsius to Fahrenheit
       const fahrenheit = (value * 9/5) + 32;
       return `${value}°C is ${fahrenheit.toFixed(2)}°F`;
